describe('Date Picker Keyboard Accessibility', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.get('[data-testid="date-picker-input"]').as('dateInput');
    cy.get('[data-testid="date-picker-calendar"]').as('calendar');
  });

  it('should open date picker with Enter key and navigate months with arrow keys', () => {
    cy.get('@dateInput').focus();
    cy.get('@dateInput').type('{enter}');
    cy.get('@calendar').should('be.visible');

    cy.get('@calendar').type('{rightarrow}');
    cy.get('[data-testid="calendar-month"]').should('contain', 'February');

    cy.get('@calendar').type('{leftarrow}');
    cy.get('[data-testid="calendar-month"]').should('contain', 'January');
  });

  it('should select date with keyboard and close picker with Escape', () => {
    cy.get('@dateInput').focus();
    cy.get('@dateInput').type('{enter}');
    cy.get('@calendar').should('be.visible');

    cy.get('[data-testid="calendar-day-15"]').focus();
    cy.get('[data-testid="calendar-day-15"]').type('{enter}');

    cy.get('@dateInput').should('have.value', /15/);
    cy.get('@calendar').should('not.be.visible');
  });

  it('should navigate between days using Tab key and select with Space', () => {
    cy.get('@dateInput').focus();
    cy.get('@dateInput').type('{enter}');
    cy.get('@calendar').should('be.visible');

    cy.get('[data-testid="calendar-day-1"]').focus();
    cy.focused().should('have.attr', 'data-testid', 'calendar-day-1');

    cy.get('@calendar').type('{tab}');
    cy.focused().should('have.attr', 'data-testid', 'calendar-day-2');

    cy.get('@calendar').type('{shift+tab}');
    cy.focused().should('have.attr', 'data-testid', 'calendar-day-1');

    cy.get('@calendar').type(' ');
    cy.get('@dateInput').should('have.value', /1/);
  });

  it('should navigate to previous and next months with keyboard shortcuts', () => {
    cy.get('@dateInput').focus();
    cy.get('@dateInput').type('{enter}');
    cy.get('@calendar').should('be.visible');

    cy.get('[data-testid="calendar-month"]').should('contain', 'January');

    cy.get('@calendar').type('{pagedown}');
    cy.get('[data-testid="calendar-month"]').should('contain', 'February');

    cy.get('@calendar').type('{pageup}');
    cy.get('[data-testid="calendar-month"]').should('contain', 'January');
  });

  it('should close date picker with Escape key without selecting date', () => {
    cy.get('@dateInput').focus();
    cy.get('@dateInput').type('{enter}');
    cy.get('@calendar').should('be.visible');

    cy.get('@calendar').type('{esc}');
    cy.get('@calendar').should('not.be.visible');
    cy.get('@dateInput').should('have.value', '');
  });

  it('should handle edge case of navigating to year boundaries with keyboard', () => {
    cy.get('@dateInput').focus();
    cy.get('@dateInput').type('{enter}');
    cy.get('@calendar').should('be.visible');

    cy.get('[data-testid="calendar-year-selector"]').focus();
    cy.get('[data-testid="calendar-year-selector"]').type('{uparrow}');
    cy.get('[data-testid="calendar-year"]').should('contain', new Date().getFullYear() + 1);

    cy.get('[data-testid="calendar-year-selector"]').type('{downarrow}');
    cy.get('[data-testid="calendar-year"]').should('contain', new Date().getFullYear());
  });

  it('should maintain focus management when cycling through date picker elements', () => {
    cy.get('@dateInput').focus();
    cy.get('@dateInput').type('{enter}');

    cy.get('[data-testid="calendar-day-10"]').focus();
    cy.focused().should('have.attr', 'data-testid', 'calendar-day-10');

    cy.get('[data-testid="calendar-day-10"]').type('{enter}');
    cy.get('@dateInput').should('have.focus');
    cy.get('@dateInput').should('have.value', /10/);
  });
});
